import{_ as a,o,c as r,a2 as t}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Atajos de teclado (Configuración)","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/hotkeys-page.md","filePath":"es-ES/user-guide/settings/hotkeys-page.md","lastUpdated":1787788413000}'),i={name:"es-ES/user-guide/settings/hotkeys-page.md"};function n(l,e,s,c,d,g){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="atajos-de-teclado-configuracion" tabindex="-1">Atajos de teclado (Configuración) <a class="header-anchor" href="#atajos-de-teclado-configuracion" aria-label="Permalink to &quot;Atajos de teclado (Configuración)&quot;">​</a></h1><p>La página de Atajos de teclado centraliza la gestión de atajos de invocación global, teclas de navegación interna, accesos rápidos de plugins y reglas de listas negras de procesos. Contiene tres pestañas: <strong>Global</strong>, <strong>Acciones de plugins</strong> y <strong>Lista negra de procesos</strong>.</p><h2 id="_1-global" tabindex="-1">1. Global <a class="header-anchor" href="#_1-global" aria-label="Permalink to &quot;1. Global&quot;">​</a></h2><h3 id="atajos-globales" tabindex="-1">Atajos globales <a class="header-anchor" href="#atajos-globales" aria-label="Permalink to &quot;Atajos globales&quot;">​</a></h3><ul><li><strong>Mostrar/Ocultar búsqueda rápida</strong>: Grabador de teclas dedicado. Admite <strong>modo de doble pulsación</strong> (por defecto doble <code>Ctrl</code>, configurable a doble <code>Alt</code> o <code>Shift</code>) y <strong>combinaciones estándar</strong> (p. ej. <code>Alt+Space</code>, <code>Win+Space</code>).</li><li><strong>Abrir el panel principal de forma predeterminada</strong>: Casilla (desactivada por defecto). Al activarla, el atajo global abre la Ventana principal en lugar de la Ventana rápida. La primera vez solo la lleva al primer plano y le da el foco; si está visible pero inactiva la vuelve a activar, y si ya está activa la cierra al pulsar de nuevo. No se mantiene automáticamente siempre encima.</li><li><strong>Responder al enfocar aplicaciones a pantalla completa</strong>: Casilla (desactivada por defecto). Permite responder a los atajos incluso con juegos o reproductores a pantalla completa; si está desactivada, los atajos se omiten para no interrumpir.</li><li><strong>Salto rápido (Quick Jump)</strong>: Por defecto <code>Ctrl+G</code>. En diálogos de archivos, salta a la carpeta navegada recientemente en exploradores compatibles.</li></ul><h3 id="teclas-de-funcion-y-navegacion" tabindex="-1">Teclas de función y navegación <a class="header-anchor" href="#teclas-de-funcion-y-navegacion" aria-label="Permalink to &quot;Teclas de función y navegación&quot;">​</a></h3><p>Controles independientes de grabación de teclas que aceptan combinaciones personalizadas:</p><ul><li><strong>Seleccionar elemento siguiente / anterior</strong>: Por defecto <code>Ctrl+N</code> / <code>Ctrl+P</code> (equivalente a <code>↓</code> / <code>↑</code>).</li><li><strong>Modificador de salto numérico</strong>: Por defecto <code>Ctrl</code>, combinado con números <code>1</code>–<code>9</code>.</li><li><strong>Abrir Menú de acciones</strong>: Por defecto <code>Ctrl+O</code> (equivalente a <code>→</code>).</li><li><strong>Autocompletar desde selección</strong>: Por defecto <code>Ctrl+Tab</code>.</li><li><strong>Vista previa instantánea QuickLook</strong>: Por defecto <code>Alt+P</code>.</li><li><strong>Término anterior / siguiente en historial</strong>: Por defecto <code>Alt+Up</code> / <code>Alt+Down</code>.</li><li><strong>Eliminar término del historial</strong>: Por defecto <code>Ctrl+Delete</code>.</li><li><strong>Abrir Ventana principal</strong>: Por defecto <code>Ctrl+F</code>.</li><li><strong>Abrir ventana LocalSend</strong>: Por defecto <code>Ctrl+S</code>.</li><li><strong>Fijar ventana (Mantener visible)</strong>: Por defecto <code>Ctrl+T</code>.</li><li><strong>Mostrar/Ocultar Panel rápido</strong>: Por defecto <code>Ctrl+F2</code>.</li></ul><h3 id="activadores-de-raton-para-navegacion-rapida" tabindex="-1">Activadores de ratón para Navegación rápida <a class="header-anchor" href="#activadores-de-raton-para-navegacion-rapida" aria-label="Permalink to &quot;Activadores de ratón para Navegación rápida&quot;">​</a></h3><ul><li><strong>Doble clic izquierdo en zona vacía</strong>: Casilla (activada por defecto). Abre el menú de Navegación rápida en el escritorio o en el Explorador.</li><li><strong>Clic central en zona vacía</strong>: Casilla (activada por defecto). Abre el menú en el escritorio, Explorador o cuadros de diálogo.</li></ul><h2 id="_2-acciones-de-plugins" tabindex="-1">2. Acciones de plugins <a class="header-anchor" href="#_2-acciones-de-plugins" aria-label="Permalink to &quot;2. Acciones de plugins&quot;">​</a></h2><p>Muestra todos los atajos registrados por plugins (p. ej. Copiar ruta completa <code>Ctrl+Shift+C</code>, Cortar <code>Ctrl+X</code>, Copiar <code>Ctrl+C</code>, Pegar <code>Ctrl+V</code>, Eliminar <code>Delete</code>, Eliminación permanente <code>Shift+Delete</code>).</p><ul><li><strong>Vista agrupada</strong>: Organizado con claridad por plugin de origen.</li><li><strong>Reasignación individual</strong>: Cada acción cuenta con su propio control de grabación.</li></ul><h2 id="_3-lista-negra-de-procesos" tabindex="-1">3. Lista negra de procesos <a class="header-anchor" href="#_3-lista-negra-de-procesos" aria-label="Permalink to &quot;3. Lista negra de procesos&quot;">​</a></h2><p>Configura aplicaciones en primer plano ante las cuales Lertaro silenciará todos los atajos y activadores de ratón.</p><ul><li><strong>Sin distinción de mayúsculas</strong>: Acepta <code>game.exe</code> o <code>game</code>.</li><li><strong>Añadir individualmente</strong>: Introduce el nombre del proceso y pulsa <strong>Añadir proceso</strong>.</li><li><strong>Gestión por lotes</strong>: Pulsa <strong>Generar texto</strong> para exportar la lista a texto multilínea, o pega una lista y pulsa <strong>Aplicar a la lista</strong>.</li><li><strong>Exención automática en cuadros de diálogo</strong>: Aunque una app esté en la lista negra, sus diálogos de selección de archivos conservan la Búsqueda incrustada y la Navegación rápida.</li></ul>',16)])])}const m=a(i,[["render",n]]);export{u as __pageData,m as default};
